<script setup lang="ts">
definePageMeta({ middleware: 'auth' }); const { role } = useAuth(); const { mine, forStudent } = useAcademicRecords(); const { list } = useStudents(); const selectedStudentId = ref<number | ''>(''); const record = ref(); const { data: students } = role.value === 'registrar' ? await useAsyncData('record-students', () => list({ per_page: 100 })) : { data: ref(null) }; if (role.value === 'student') record.value = await mine(); async function loadRecord() { if (selectedStudentId.value) record.value = await forStudent(Number(selectedStudentId.value)) }
</script>
<template><div class="page-shell"><PageHeader title="Academic record" description="Derived from enrollments, offerings, courses, terms, and grades." /><BaseCard v-if="role === 'registrar'"><FormField for="record-student" label="Student"><BaseSelect id="record-student" v-model="selectedStudentId" :options="(students?.data ?? []).map(item => ({ label: `${item.student_number} · ${item.last_name}, ${item.first_name}`, value: item.id }))" /></FormField><BaseButton class="mt-4" :disabled="!selectedStudentId" @click="loadRecord">View record</BaseButton></BaseCard><AcademicRecordView v-if="record" :record="record" /></div></template>
